    # In the examples, marker 1 radiates leftward from its inward tip; isolated
    # marker 3s radiate away from a diagonal border pattern, recolored 4 at origin.
    # Here 9 is background. Row-1 segments point left, bottom-left segments point right.
    for r, row in enumerate(grid):
        ones = [c for c, v in enumerate(row) if v == 1]
        if ones:
            lo, hi = min(ones), max(ones)
            if lo == 0:
                out[r][hi] = 4
                for c in range(hi + 1, w):
                    if row[c] == 9: out[r][c] = 1
            elif hi == w - 1:
                # right-end segment points left, with the innermost seed as 4
                out[r][lo] = 4
                for c in range(lo - 1, -1, -1):
                    if row[c] == 9: out[r][c] = 1
    # The diagonal 3s form two paired slanted strokes. Color their connecting
    # cells 3 and turn the source-side endpoint into 4.
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r,c in pts:
        # connect adjacent diagonal points in same pattern, filling aligned gaps
        for rr,cc in pts:
